const assets = {"/index.html":{"contentType":"text/html; charset=utf-8","body":""},"/rest-in-bass.mp3":{"contentType":"audio/mpeg","body":""},"/src/assets/camera-crew.jpg":{"contentType":"image/jpeg","body":""},"/src/assets/camera-floor.jpg":{"contentType":"image/jpeg","body":""},"/src/assets/crew-group.jpg":{"contentType":"image/jpeg","body":""},"/src/assets/hero-reference.jpg":{"contentType":"image/jpeg","body":""},"/src/assets/skate-rail.jpg":{"contentType":"image/jpeg","body":""},"/src/assets/skate-stairs.jpg":{"contentType":"image/jpeg","body":""},"/src/main.js":{"contentType":"text/javascript; charset=utf-8","body":""},"/src/style.css":{"contentType":"text/css; charset=utf-8","body":""},"/":{"contentType":"text/html; charset=utf-8","body":""}};

function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const pathname = decodeURIComponent(url.pathname);
    const asset = assets[pathname] || assets["/index.html"];
    return new Response(decodeBase64(asset.body), {
      headers: {
        "content-type": asset.contentType,
        "cache-control": pathname === "/" || pathname.endsWith(".html")
          ? "no-cache"
          : "public, max-age=31536000, immutable"
      }
    });
  }
};
